@@ -0,0 +1,71 @@
+import { createHmac } from "crypto";
+
+export interface SessionTokenPayload {
+  id: string;
+  userId: string;
+  issuedAt: number;
+  expiresAt: number;
+}
+
+const getSigningKey = (): string => {
+  const key = process.env.SESSION_SIGNING_KEY;
+  if (!key) {
+    throw new Error("SESSION_SIGNING_KEY environment variable is not set");
+  }
+  return key;
+};
+
+export const createSessionToken = (
+  id: string,
+  userId: string,
+  expiresInSeconds: number = 3600,
+): string => {
+  const now = Math.floor(Date.now() / 1000);
+  const payload: SessionTokenPayload = {
+    id,
+    userId,
+    issuedAt: now,
+    expiresAt: now + expiresInSeconds,
+  };
+
+  const payloadJson = JSON.stringify(payload);
+  const header = JSON.stringify({ alg: "HS256", typ: "JWT" });
+
+  const headerB64 = Buffer.from(header).toString("base64url");
+  const payloadB64 = Buffer.from(payloadJson).toString("base64url");
+  const message = `${headerB64}.${payloadB64}`;
+
+  const signature = createHmac("sha256", getSigningKey())
+    .update(message)
+    .digest("base64url");
+
+  return `${message}.${signature}`;
+};
+
+export const verifySessionToken = (token: string): SessionTokenPayload => {
+  const parts = token.split(".");
+  if (parts.length !== 3) {
+    throw new Error("Invalid token format");
+  }
+
+  const [headerB64, payloadB64, signatureB64] = parts;
+  const message = `${headerB64}.${payloadB64}`;
+
+  const expectedSignature = createHmac("sha256", getSigningKey())
+    .update(message)
+    .digest("base64url");
+
+  if (signatureB64 !== expectedSignature) {
+    throw new Error("Invalid token signature");
+  }
+
+  const payloadJson = Buffer.from(payloadB64, "base64url").toString();
+  const payload: SessionTokenPayload = JSON.parse(payloadJson);
+
+  const now = Math.floor(Date.now() / 1000);
+  if (payload.expiresAt < now) {
+    throw new Error("Token has expired");
+  }
+
+  return payload;
+};
